/// APPEND-ONLY kardex ledger (FASE 4). One row per posted movement; DB
/// triggers reject every UPDATE and DELETE — corrections are new movements
/// (adjustments). Valuation is weighted moving average kept SEPARATELY per
/// currency (see docs/fixtures-fase4-kardex.json, generated by the
/// independent oracle tools/golden-kardex.py):
///   - entries add round2(qty × unit_cost); the VES side comes from
///     round2(cost_usd × the BCV rate of the SOURCE document), never from
///     converting the USD inventory value;
///   - exits cost round2(qty × avg) with avg = round6(value / qty); exits
///     never change the average;
///   - when quantity reaches (or crosses) zero the residual value is zeroed.
/// Quantities carry 4 decimals, values 2, averages 6 — ROUND_HALF_UP.
/// `seq` is the per-product posting sequence assigned under the
/// product_balances row lock (SELECT ... FOR UPDATE): the authoritative
/// kardex order, race-free by construction.
#[derive(Debug, Clone, PartialEq, ::corvis_orm::serde::Serialize, ::corvis_orm::serde::Deserialize, ::corvis_orm::Model)]
#[serde(crate = "::corvis_orm::serde")]
#[model(
    table = "inventory_movements",
    unique(fields = ["productId", "seq"]),
    index(fields = ["purchaseId"]),
    index(fields = ["invoiceId"]),
    index(fields = ["fiscalNoteId"]),
)]
pub struct InventoryMovement {
    #[id]
    #[default(uuid)]
    #[db("Uuid")]
    pub id: ::std::string::String,
    #[serde(rename = "productId")]
    #[db("Uuid")]
    pub product_id: ::std::string::String,
    pub seq: i32,
    pub kind: InventoryMovementKind,
    /// Magnitude, always > 0 (DB CHECK); `kind` determines the direction.
    #[db("Decimal(18,4)")]
    pub qty: ::corvis_orm::Decimal,
    /// Entries: the source document's net unit cost. Exits: the average used.
    #[serde(rename = "unitCostUsd")]
    #[db("Decimal(18,6)")]
    pub unit_cost_usd: ::corvis_orm::Decimal,
    #[serde(rename = "unitCostVes")]
    #[db("Decimal(18,6)")]
    pub unit_cost_ves: ::corvis_orm::Decimal,
    /// Entries: round2(qty × unit_cost_usd) / round2(usd × bcv).
    /// Exits: round2(qty × avg) per currency (the COGS of the movement).
    #[serde(rename = "totalCostUsd")]
    #[db("Decimal(18,2)")]
    pub total_cost_usd: ::corvis_orm::Decimal,
    #[serde(rename = "totalCostVes")]
    #[db("Decimal(18,2)")]
    pub total_cost_ves: ::corvis_orm::Decimal,
    /// Resulting balance snapshot AFTER this movement.
    #[serde(rename = "balanceQty")]
    #[db("Decimal(18,4)")]
    pub balance_qty: ::corvis_orm::Decimal,
    #[serde(rename = "balanceValueUsd")]
    #[db("Decimal(18,2)")]
    pub balance_value_usd: ::corvis_orm::Decimal,
    #[serde(rename = "balanceValueVes")]
    #[db("Decimal(18,2)")]
    pub balance_value_ves: ::corvis_orm::Decimal,
    #[serde(rename = "avgUnitCostUsd")]
    #[db("Decimal(18,6)")]
    pub avg_unit_cost_usd: ::corvis_orm::Decimal,
    #[serde(rename = "avgUnitCostVes")]
    #[db("Decimal(18,6)")]
    pub avg_unit_cost_ves: ::corvis_orm::Decimal,
    /// Entries only: the BCV rate that valued the VES side.
    #[serde(rename = "bcvRate")]
    #[db("Decimal(18,8)")]
    pub bcv_rate: ::std::option::Option<::corvis_orm::Decimal>,
    /// True when this exit was allowed to drive the balance below zero
    /// (negative_stock_policy = ALLOW): the recorded discrepancy.
    #[serde(rename = "negativeStock")]
    #[default(false)]
    pub negative_stock: bool,
    /// Source document (DB CHECK: exactly the ref matching `kind` is set;
    /// adjustments carry a reason instead).
    #[serde(rename = "purchaseId")]
    #[db("Uuid")]
    pub purchase_id: ::std::option::Option<::std::string::String>,
    #[serde(rename = "invoiceId")]
    #[db("Uuid")]
    pub invoice_id: ::std::option::Option<::std::string::String>,
    #[serde(rename = "fiscalNoteId")]
    #[db("Uuid")]
    pub fiscal_note_id: ::std::option::Option<::std::string::String>,
    pub reason: ::std::option::Option<::std::string::String>,
    #[serde(rename = "occurredAt")]
    pub occurred_at: ::corvis_orm::DateTime,
    #[serde(rename = "createdById")]
    #[db("Uuid")]
    pub created_by_id: ::std::string::String,
    #[serde(rename = "createdAt")]
    #[default(now)]
    pub created_at: ::corvis_orm::DateTime,
    #[relation(belongs_to, fields = ["productId"], references = ["id"])]
    #[serde(default, skip_serializing_if = "::std::option::Option::is_none")]
    pub product: ::std::option::Option<::std::boxed::Box<Product>>,
    #[relation(belongs_to, fields = ["purchaseId"], references = ["id"])]
    #[serde(default, skip_serializing_if = "::std::option::Option::is_none", with = "::corvis_orm::serde_helpers::double_option")]
    pub purchase: ::std::option::Option<::std::option::Option<::std::boxed::Box<Purchase>>>,
    #[relation(belongs_to, fields = ["invoiceId"], references = ["id"])]
    #[serde(default, skip_serializing_if = "::std::option::Option::is_none", with = "::corvis_orm::serde_helpers::double_option")]
    pub invoice: ::std::option::Option<::std::option::Option<::std::boxed::Box<Invoice>>>,
    #[serde(rename = "fiscalNote")]
    #[relation(belongs_to, fields = ["fiscalNoteId"], references = ["id"])]
    #[serde(default, skip_serializing_if = "::std::option::Option::is_none", with = "::corvis_orm::serde_helpers::double_option")]
    pub fiscal_note: ::std::option::Option<::std::option::Option<::std::boxed::Box<FiscalNote>>>,
    #[serde(rename = "createdBy")]
    #[relation(belongs_to, fields = ["createdById"], references = ["id"], name = "InventoryMovementCreatedBy")]
    #[serde(default, skip_serializing_if = "::std::option::Option::is_none")]
    pub created_by: ::std::option::Option<::std::boxed::Box<User>>,
}

/// Running per-product balance, denormalized from the movements. This row is
/// the CONCURRENCY ANCHOR: every movement locks it with SELECT ... FOR UPDATE
