/// Append-only fiscal audit trail: who changed what, when, and the fiscal
/// facts that matter at that instant (document numbers, totals, rates).
///
/// Append-only is enforced by DB triggers (UPDATE and DELETE both raise
/// FISCAL_IMMUTABLE), exactly like invoices and inventory movements. The
/// application cannot rewrite history even with a bug.
///
/// Rows are written INSIDE the same transaction as the mutation they describe:
/// if the invoice rolls back, its audit row rolls back with it, so the log can
/// never claim something that did not happen.
#[derive(Debug, Clone, PartialEq, ::corvis_orm::serde::Serialize, ::corvis_orm::serde::Deserialize, ::corvis_orm::Model)]
#[serde(crate = "::corvis_orm::serde")]
#[model(
    table = "fiscal_audit_logs",
    index(fields = ["action", "createdAt"]),
    index(fields = ["entity", "entityId"]),
    index(fields = ["createdAt"]),
)]
pub struct FiscalAuditLog {
    #[id]
    #[default(uuid)]
    #[db("Uuid")]
    pub id: ::std::string::String,
    pub action: FiscalAuditAction,
    /// Table the mutation landed on (`invoices`, `payments`, ...).
    #[db("VarChar(64)")]
    pub entity: ::std::string::String,
    /// Primary key of the affected row. Null only for mutations with no single
    /// target row.
    #[serde(rename = "entityId")]
    #[db("Uuid")]
    pub entity_id: ::std::option::Option<::std::string::String>,
    #[serde(rename = "actorId")]
    #[db("Uuid")]
    pub actor_id: ::std::string::String,
    /// Fiscal snapshot: document/control numbers, amounts, currency, reason.
    /// Money is serialized as string, never as a JSON number.
    #[db("JsonB")]
    pub summary: ::corvis_orm::serde_json::Value,
    #[serde(rename = "createdAt")]
    #[default(now)]
    pub created_at: ::corvis_orm::DateTime,
    #[relation(belongs_to, fields = ["actorId"], references = ["id"], name = "FiscalAuditLogActor")]
    #[serde(default, skip_serializing_if = "::std::option::Option::is_none")]
    pub actor: ::std::option::Option<::std::boxed::Box<User>>,
}

